/**
 * Time window for the metric series. Bounds are epoch **seconds** (Analytics Engine stores the event timestamp in seconds). `to` must be strictly greater than `from`.
 */
export type GetMetricSeriesRequest = {
    /**
     * Window start, epoch seconds (inclusive).
     */
    from: number;
    /**
     * Window end, epoch seconds (exclusive). Must be greater than `from`.
     */
    to: number;
    /**
     * Bucket width in seconds (60s–86400s/1d). Defaults to `3600` (hourly). Each returned point is floor-aligned to this width.
     */
    bucket?: number;
};

/**
 * Bucketed values for one metric, compiled from its typed IR and executed against the Analytics Engine SQL API, plus the SQL that produced them. Capped at 5000 rows (high-cardinality `groupBy` series are truncated).
 */
export type GetMetricSeriesResponse = {
    /**
     * The Analytics Engine SQL executed to produce `rows` (echoed for transparency / debugging).
     */
    sql: string;
    /**
     * Bucketed series, ordered by `t` ascending. For a metric with a `groupBy` clause each bucket has one row per label combination, with the label values as extra string/number properties on the row.
     */
    rows: Array<{
        /**
         * Bucket start, epoch seconds, floor-aligned to `bucket`.
         */
        t: number;
        /**
         * Aggregated metric value in the bucket (sample-interval weighted).
         */
        v: number;
        /**
         * Lower edge of the seasonal band — what this hour of the week normally holds, `sigma` below the median of the four weeks before the window. Present only for a metric whose `display.band` is on, and always alongside `hi`.
         *
         */
        lo?: number;
        /**
         * Upper edge of the seasonal band. Present only for a metric whose `display.band` is on, and always alongside `lo`. A point outside `[lo, hi]` is exactly a bucket an `anomaly` alert rule at the same sigma would breach on — the band a chart draws and the condition a rule fires on come from one fit.
         *
         */
        hi?: number;
        [key: string]: unknown;
    }>;
};

/**
 * Every catalogued event in the project (including pending auto-discovered names).
 */
export type ListEventsResponse = Array<{
    /**
     * Stable opaque event id.
     */
    id: string;
    /**
     * Event name — the handle metric queries reference.
     */
    name: string;
    /**
     * Folder the event is filed under, or `null` if at the root.
     */
    folder?: string | null | null;
    /**
     * Human-readable description, or `null` if none set.
     */
    description: string | null;
    /**
     * Typed properties declared on the event.
     */
    properties: Array<{
        /**
         * Property key, e.g. `amount` or `plan`. Must be a bare identifier — it is emitted as a SQL alias when the property is used as a `by()` dimension, and there is no way to quote one in the Analytics Engine dialect.
         */
        name: string;
        /**
         * Value type of the property as recorded on the event.
         */
        type: 'string' | 'number' | 'boolean';
        /**
         * Whether the property must be present on every emitted event.
         */
        required?: boolean;
        /**
         * Human-readable description of the property.
         */
        description?: string;
        /**
         * `true` when this property was DISCOVERED in live traffic rather than declared. Nothing is recorded for it yet — a property is written to Analytics Engine only once it owns a column, and a column is allocated when an admin declares the property (include it in a `PATCH .../events/{id}` body). Approval is a gate rather than a formality: columns are finite and permanently reserved, so auto-allocating them from customer payload keys would exhaust an event's schema irreversibly.
         */
        pending?: boolean;
    }>;
    /**
     * `1` if this is an auto-discovered name awaiting approval (metrics on it fail until approved), `0` if approved/usable.
     */
    pending: number;
    /**
     * ISO-8601 timestamp of creation.
     */
    createdAt: string;
}>;

