/**
 * Lifecycle status of a queue item. The working flow is `open` → `in_progress` → `ready_for_qa` → `resolved` (or `wont_fix`, terminal from any earlier stage). `blocked` marks an item that can't progress until an external dependency clears — a working state a human sets and clears. `ready_for_qa` is what a developer sets once a fix lands; `resolved` is the QA sign-off, normally flipped in the dashboard after verification — set it directly from code only when the fix has been verified end-to-end. `investigating_by_ai` is a system-owned display state — set when the AI agent (Jarvis) picks an item up to investigate, never chosen by a human — so it is shown but not offered as a manual choice. `pending_approval` is the one human-gated holding state: it parks an item OUT of the work queue until a human promotes it to `open` in the dashboard, so `GET /api/admin/ops` excludes it under `status=all`/default and returns it only when requested as an exact `status`. It covers untriaged inbound that must never be auto-implemented — connector requests filed from a customer's connectors panel, and questions funnelled in from the "Stuck in onboarding?" assistant — where approving means flipping the status to `open`. Two earlier values were removed in favour of this single gate: `triage` (the onboarding-help bucket, now `pending_approval`) and `triaged` (a redundant "looked at but not started" step, now plain `open`).
 */
export type OpsItemStatus = 'open' | 'pending_approval' | 'investigating_by_ai' | 'in_progress' | 'blocked' | 'ready_for_qa' | 'resolved' | 'wont_fix';

/**
 * Triage priority of a queue item. The lowest tier is `nice_to_have` (not `low`) — carried over from the feature-request "importance" scale this priority set replaced.
 */
export type OpsItemPriority = 'nice_to_have' | 'medium' | 'high' | 'critical';

/**
 * Where automation has taken an item in the investigation lifecycle — the signal the ops cockpit renders as "what AI did" plus the one action expected of the user. It is **written as a side-effect of the actions that already happen**, never authored on its own: linking a PR sets `pr_ready`, moving to `in_progress` sets `working`, `ready_for_qa` sets `ready_for_qa`, a system/assistant reply sets `question`, resolving clears it, and creation seeds `backlog` or `investigated`/`detected` for auto-filed error/alert tickets. `backlog` is the single "nothing has happened yet" state — how urgent that is reads off `priority`, not off a separate state, and its one action is to hand the item to an agent. `pr_merged` and `pr_closed` are written by the GitHub `pull_request` webhook when the linked PR reaches a terminal outcome — merged (the fix shipped, resolve the item) or closed without merging (the fix was rejected, decide what happens next). Absent on rows filed before the field existed — consumers should treat a missing value as "derive from the other fields".
 */
export type OpsInvestigationState = 'pr_ready' | 'pr_merged' | 'pr_closed' | 'investigated' | 'detected' | 'question' | 'ready_for_qa' | 'pending_approval' | 'working' | 'backlog';

/**
 * Auto-collected browser environment for a `bug`/`feature_request`, captured at file time.
 */
export type OpsBrowserContext = {
    /**
     * URL of the page the report was filed from, or `null`.
     */
    pageUrl?: string | null;
    /**
     * Reporter's user-agent string, or `null`.
     */
    userAgent?: string | null;
    /**
     * Reporter's viewport (e.g. `1280x720`), or `null`.
     */
    viewport?: string | null;
    [key: string]: unknown;
};

/**
 * Hydrated detail for an auto-filed `error` ticket, read from the tracked `errors` row at request time (so `count`/`lastSeenAt` reflect the latest state).
 */
export type OpsErrorContext = {
    /**
     * The tracked `errors` row id (fetch full detail via `related.error`).
     */
    id: string;
    /**
     * Stable dedupe key of the tracked error.
     */
    fingerprint: string;
    /**
     * Fingerprint of the upstream issue this error descends from (set when the same error was reported at an inner boundary first), or `null` for a root issue.
     */
    causedByFingerprint?: string | null;
    /**
     * Error class/name, e.g. `TypeError`, or `null` when the source didn't supply one.
     */
    errorType?: string | null;
    /**
     * The error message.
     */
    message: string;
    /**
     * The `see()` consequence subject — the `causes_the(<subject>)` value. Grep the codebase for this to find the throw site. `null` if the error was never instrumented.
     */
    subject?: string | null;
    /**
     * The `see()` consequence outcome — the `.to(<outcome>)` value. `null` if uninstrumented.
     */
    outcome?: string | null;
    /**
     * `see()` error kind: `caught` | `uncaught` | `unhandled_rejection` | `network` | `violation`.
     */
    kind?: string | null;
    /**
     * Which SDK side reported it: `client` | `server`.
     */
    side?: string | null;
    /**
     * Published env the reporting SDK ran against (dev/staging/prod).
     */
    env?: string | null;
    /**
     * Folded occurrence count for this fingerprint.
     */
    count: number;
    /**
     * ISO-8601 timestamp of the first occurrence.
     */
    firstSeenAt: string;
    /**
     * ISO-8601 timestamp of the most recent occurrence.
     */
    lastSeenAt: string;
    /**
     * Distinct, id-normalized routes this error has surfaced on (UUIDs/ids collapsed to `#`).
     */
    seenUrls: Array<string>;
    /**
     * The last 3 non-empty lines of the latest occurrence's stack — the innermost frames closest to where the throw bubbled out, baked in as an at-a-glance locator. `null` when the source supplied no stack. Fetch the full stack via `related.error`.
     */
    stackTail?: string | null;
    /**
     * @shipeasy/sdk version of the latest occurrence, or `null`.
     */
    sdkVersion?: string | null;
    [key: string]: unknown;
};

/**
 * The condition of a metric-rule alert.
 */
export type OpsAlertRuleSummary = {
    /**
     * Alert-rule id.
     */
    id: string;
    /**
     * Alert-rule name.
     */
    name: string;
    /**
     * How `observedValue` is compared to `threshold`.
     */
    comparator: 'gt' | 'gte' | 'lt' | 'lte';
    /**
     * The threshold value the rule fires on.
     */
    threshold: number;
    /**
     * Rolling evaluation window in hours.
     */
    windowHours: number;
    [key: string]: unknown;
};

/**
 * The metric an alert watches, with its backing events.
 */
export type OpsAlertMetricSummary = {
    /**
     * Metric id (fetch full detail via `related.metric`).
     */
    id: string;
    /**
     * Metric name.
     */
    name: string;
    /**
     * The event name(s) the metric aggregates over — one for count metrics, numerator + denominator for ratio metrics. Grep the codebase for `track('<event>')` on each to find the instrumentation feeding the metric.
     */
    events: Array<string>;
    [key: string]: unknown;
};

/**
 * Detail for an `alert` ticket — the fired-alert INSTANCE this ticket is. List rows carry the stored capture subset (`source`, `dedupeKey`, `ruleId`, `detail`, `href`, `observedValue`); the single-item read hydrates the rest, resolving `severity`/`status` off the ticket itself and the rule → metric → event chain at request time.
 */
export type OpsAlertContext = {
    /**
     * What kind of condition opened this alert instance.
     */
    source: 'metric_rule' | 'killswitch_armed' | 'experiment_srm' | 'experiment_peek' | 'guardrail';
    /**
     * Stable per-condition key; with `source` forms the ticket's `sourceRef`.
     */
    dedupeKey: string;
    /**
     * The instance's one-line reading — the observed condition in words.
     */
    detail?: string | null;
    /**
     * Id of the alert rule that opened this instance, or `null` for a built-in condition.
     */
    ruleId?: string | null;
    /**
     * How loud the alert is. Severity belongs to the RULE and is carried by this ticket as `priority`; it is DERIVED from that on the hydrated single-item read, and absent from the raw stored context list rows return.
     */
    severity?: 'danger' | 'warn' | 'info';
    /**
     * The metric value that tripped the rule, or `null`.
     */
    observedValue?: number | null;
    /**
     * Dashboard deep link to the alert, or `null`.
     */
    href?: string | null;
    /**
     * Firing state of this instance, projected from the ticket's own status (`active` while it is open, i.e. while the condition holds). Absent from the raw stored context list rows return.
     */
    status?: 'active' | 'resolved' | 'dismissed' | null;
    /**
     * ISO-8601 timestamp the alert became active, or `null`.
     */
    activeSince?: string | null;
    /**
     * ISO-8601 timestamp the alert cleared, or `null` while still active.
     */
    resolvedAt?: string | null;
    /**
     * The alert rule condition that tripped (metric-rule alerts only); `null` for SRM/peek/guardrail alerts with no rule.
     */
    rule?: OpsAlertRuleSummary | null;
    /**
     * The metric the alert watches, hydrated with its backing event(s); `null` if not resolvable.
     */
    metric?: OpsAlertMetricSummary | null;
    [key: string]: unknown;
};

